import{_ as o,o as t,c as d,a2 as a}from"./chunks/framework.BM5YPQmL.js";const h=JSON.parse('{"title":"3.0.0-WP-l1apps-merge","description":"","frontmatter":{},"headers":[],"relativePath":"zh/release/3.0.0-WP-l1apps-merge.md","filePath":"zh/release/3.0.0-WP-l1apps-merge.md"}'),r={name:"zh/release/3.0.0-WP-l1apps-merge.md"};function l(c,e,s,i,n,p){return t(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="_3-0-0-wp-l1apps-merge" tabindex="-1">3.0.0-WP-l1apps-merge <a class="header-anchor" href="#_3-0-0-wp-l1apps-merge" aria-label="Permalink to &quot;3.0.0-WP-l1apps-merge&quot;">​</a></h1><p>合并应用发布：200+ 条散落的命令获得了一个按意图驱动的 前门，文档也为这个时代从头重写。</p><h2 id="_8-个合并大应用" tabindex="-1">8 个合并大应用 <a class="header-anchor" href="#_8-个合并大应用" aria-label="Permalink to &quot;8 个合并大应用&quot;">​</a></h2><p><code>update</code>、<code>disk-tool</code>、<code>net-tool</code>、<code>sound-tool</code>、<code>files</code>、 <code>sysdiag</code>、<code>hwinfo</code>、<code>power</code>——每个应用有三扇门：</p><ul><li><strong>无参数</strong>——意图向导：单键菜单、 自动检测、跨域修复（<code>update</code> 向导在真正检查更新之前， 先通过 DHCP 修复缺失的 IP、通过 <code>lsblk</code> + <code>abdisk</code> 修复 缺失的 A/B 磁盘），每个破坏性路径上重输 + 裸 y 双重确认， 完全双语（<code>lang zh</code> 实时切换整个向导）。</li><li><strong><code>direct &lt;op&gt; [args]</code></strong>——显式逐字透传。</li><li><strong><code>&lt;op&gt; [args]</code></strong>——经典分发：历史 命令拼写，逐字节一致的输出。</li></ul><p>零功能损失：全部 276 条历史命令保持 注册（接口冻结；回归门禁强制下限）——程序注册表现在计数 <strong>284 个程序</strong>（+ 12 个 ush 内建 = 296 条命令）。</p><h2 id="交付了什么" tabindex="-1">交付了什么 <a class="header-anchor" href="#交付了什么" aria-label="Permalink to &quot;交付了什么&quot;">​</a></h2><ul><li><code>ocos/interface/wizard_lib.h</code>——共享的向导原语 （L1SVC 捕获、锚点探测、READLINE 询问、单键菜单、 y/N 确认）。</li><li><code>ocos/l1apps/</code> 下的 8 个应用文件夹（update 原地替换）+ 每个应用的双语 i18n 资源。</li><li><code>help -w</code> 增加领头的 <strong>mega</strong> 组（8 个应用），以及它的 l0 i18n 键。</li><li>update 向导的 5 步链：网络 -&gt; A/B 磁盘 -&gt; DNS （主机名从活动的 <code>config get update_url</code> 解析）-&gt; 检查 （已是最新则 OK 退出）-&gt; 确认安装 + 确认重启。</li><li>受防护的破坏性路径：mkfs.*、abdisk、install、rm、电源 动作（仅向导——经典/direct 为脚本保持逐字）。</li></ul><h2 id="文档-从头重写" tabindex="-1">文档，从头重写 <a class="header-anchor" href="#文档-从头重写" aria-label="Permalink to &quot;文档，从头重写&quot;">​</a></h2><ul><li><strong>用户手册</strong>（en + zh）：8 应用面地图、新的 大应用指南、经向导的上手指南、处处诚实的 命令面（<code>ush&gt;</code> 提示符时代、284 命令 注册表）。</li><li><strong>开发者集</strong>（en + zh）：Ring-3 应用开发指南—— 应用解剖、带输出锚点契约的 L1SVC 面地图、 向导库、一份完整的编写应用教程、为 ocos/ 树重写的 服务家族页面。</li><li><strong>维护者集</strong>（en + zh）：经大应用的 故障排查、gh-pages 网站流程、本次发布的说明。</li><li>命令参考页从活动的注册表捕获重新生成 （292 页，en + zh，含 8 个大应用页面）。</li><li><code>tools/gen_api_docs.py</code> 现代化：当前树路径 （ocos/l1apps）、WP06g2 注册表行格式（<code>name [tag] hint</code>）、串口回显容忍、接线到 <code>evidence/v1_command_list.txt</code> 的 v1 基线回退。</li></ul><h2 id="验证-全部为发布树上的真实运行" tabindex="-1">验证（全部为发布树上的真实运行） <a class="header-anchor" href="#验证-全部为发布树上的真实运行" aria-label="Permalink to &quot;验证（全部为发布树上的真实运行）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>门禁</th><th>结果</th></tr></thead><tbody><tr><td><code>make all</code>（OC_RELEASE_VERSION=3.0.0-WP-l1apps-merge）</td><td>0 错误、0 警告（仅基线链接器注记）</td></tr><tr><td>完整回归（<code>tools/run_fix4_regression.py</code>）</td><td><strong>31/31</strong>（注册表下限：实测 284）</td></tr><tr><td>SSH E2E（<code>tools/ssh_g11a_e2e.py</code>）</td><td><strong>5/5 ALL PASS</strong></td></tr><tr><td>HTTPS E2E（<code>tools/run_fix4_https_e2e.py</code>）</td><td><strong>8/8</strong></td></tr><tr><td>大应用冒烟（经典分发 + 向导）</td><td><strong>21/21</strong></td></tr></tbody></table><h2 id="兼容性" tabindex="-1">兼容性 <a class="header-anchor" href="#兼容性" aria-label="Permalink to &quot;兼容性&quot;">​</a></h2><ul><li>每个历史命令名仍可解析（冻结已强制执行）。</li><li>无参数的 <code>update</code> 现在打开向导；历史上的 裸 <code>update</code> 在线流程是 <code>update direct</code>（或任何参数 形态，与从前逐字一致）。</li><li>服务输出行未变——向导与脚本探测的英文 锚点（<code>&quot;A/B disk: present&quot;</code>、<code>&quot;New version available.&quot;</code>、 <code>&quot;DHCP success: IP=&quot;</code>、<code>&quot;DNS resolution failed&quot;</code>、 <code>&quot;reboot required&quot;</code>）是契约的一部分。</li></ul>',14)])])}const u=o(r,[["render",l]]);export{h as __pageData,u as default};
